"""Render ORACLE_REPORT.md from the results document and oracle_exceptions.yml (oracle-design §7).

The report is generated; edit the exceptions file, not the report. Its "Owner decisions" section
is rendered from oracle_exceptions.yml, so decisions live in one place.
"""

from collections import Counter
from pathlib import Path
from typing import Any

import yaml

Doc = dict[str, Any]
Exceptions = dict[str, Any]  # category_a, category_b, e2e_unexplained, later_strengthening

INTRO = (
    "Generated by `uv run python scripts/run_oracle.py` (`make oracle`). Do not edit by hand: "
    "decisions go in `oracle_exceptions.yml`, and the run re-renders this file. Design: "
    "`docs/plans/oracle-design.md`; explanation: `docs/explain/oracle.md`."
)
OWNER_B = "Gold pairs the local check did not observe and no certain tag explains."
THRESHOLDS = (
    "Hand-written in `eval/oracle/thresholds.yml`. Nearest base values around each cut-off "
    "(below / at / above), and the crossings per perturbed input, summed over modes."
)
UNEXPLAINED = (
    "In the gold closure of the seed column, changed by no mode, and reachable from the seed "
    "without crossing a local category-B pair. Listed, not gated (ADR 0017)."
)


KEYS = ("category_a", "category_b", "e2e_unexplained", "later_strengthening")


def load_exceptions(path: Path) -> Exceptions:
    raw = (yaml.safe_load(path.read_text()) or {}) if path.is_file() else {}
    return {k: raw.get(k) or [] for k in KEYS}


def e2e_group(exceptions: Exceptions, seed: str, column: str) -> int | None:
    """Index of the e2e_unexplained group that covers (seed column, unobserved column)."""
    for i, g in enumerate(exceptions["e2e_unexplained"]):
        if seed in g["seeds"] and column in g["targets"]:
            return i
    return None


def e2e_ungrouped(doc: Doc, exceptions: Exceptions) -> list[tuple[str, str]]:
    """Unexplained end-to-end columns that no e2e_unexplained group gives a likely reason for."""
    return [
        (r["column"], c)
        for r in doc["e2e"]["columns"]
        for c in r["unobserved_unexplained"]
        if e2e_group(exceptions, r["column"], c) is None
    ]


def _key(case: dict[str, Any]) -> tuple[str, str]:
    return case["from"], case["to"]


def category_a(doc: Doc) -> list[tuple[str, str, str]]:
    """(from, to, check) of every category-A case, local and end-to-end."""
    out = [(c["from"], c["to"], "local") for c in doc["local"]["category_a"]]
    out += [(r["column"], t, "e2e") for r in doc["e2e"]["columns"] for t in r["category_a"]]
    return out


def owner_b(doc: Doc) -> list[tuple[str, str]]:
    """(from, to) of every untagged local category-B case."""
    return [_key(c) for c in doc["local"]["category_b"] if not c.get("tag")]


def undecided(doc: Doc, exceptions: Exceptions) -> dict[str, list[Any]]:
    """Cases that need an owner decision and have none (gated by the integration test)."""
    decided_a = {
        (e["from"], e["to"], e["check"]) for e in exceptions["category_a"] if e.get("decision")
    }
    decided_b = {_key(e) for e in exceptions["category_b"] if e.get("decision")}
    return {
        "category_a": [x for x in category_a(doc) if x not in decided_a],
        "category_b": [x for x in owner_b(doc) if x not in decided_b],
    }


def _table(header: list[str], rows: list[list[Any]]) -> list[str]:
    if not rows:
        return ["None."]
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    out += ["| " + " | ".join(str(c) for c in row) + " |" for row in rows]
    return out


def _cite(hit: dict[str, Any] | None) -> str:
    return f"{hit['line']}: `{hit['sql']}`" if hit else ""


def _summary(doc: Doc) -> list[list[Any]]:
    s, es, th = doc["local"]["summary"], doc["e2e"]["summary"], doc["thresholds"]
    tagged = ", ".join(f"{k} {v}" for k, v in s["category_b_tagged"].items()) or "0"
    zero = sum(1 for t in th["items"] if not t["total_crossings"])
    closures = f"{es['changed']} / {es['closure_direct']} / {es['closure_all']}"
    deterministic = "no" if doc["controls"]["determinism_failures"] else "yes"
    into_non_children = len(doc["drift"]["gold_pairs_into_non_children"])
    return [
        ["Control (a): base build deterministic", deterministic],
        ["Control (b): order-sensitive columns", len(doc["controls"]["order_sensitive"])],
        ["Spec `depends_on` vs manifest drift", len(doc["drift"]["depends_on"])],
        ["Gold pairs into a model that doesn't read the table", into_non_children],
        ["Threshold lines uncovered / stale", f"{len(th['uncovered'])} / {len(th['stale'])}"],
        ["Thresholds with 0 crossings", zero],
        ["Local: columns perturbed / runs", f"{s['columns_perturbed']} / {s['runs']}"],
        ["Local: gold one-hop pairs tested", s["gold_pairs"]],
        ["Local: confirmed", s["confirmed"]],
        ["Local: **category A** (changed, not in gold)", s["category_a"]],
        ["Local: category B (gold, not observed)", s["category_b"]],
        ["Local: category B auto-tagged", tagged],
        ["Local: category B for the owner", s["category_b_untagged"]],
        ["Local: confirmed through indirect pairs only", s["indirect_only"]],
        ["Local: runtime errors", s["errors"]],
        ["E2E: seed columns", es["seed_columns"]],
        ["E2E: **category A** (changed, outside the closure)", es["category_a"]],
        ["E2E: changed / direct closure / direct+indirect closure", closures],
        ["E2E: changed, reachable only through indirect edges", es["indirect_only"]],
        ["E2E: unobserved, explained by a local category-B pair", es["unobserved_explained"]],
        ["E2E: unobserved, unexplained (listed, not gated)", es["unobserved_unexplained"]],
    ]  # fmt: skip


def _thresholds(doc: Doc) -> list[list[Any]]:
    rows = []
    for t in doc["thresholds"]["items"]:
        near = "; ".join(
            f"{n['cutoff']}: {n['nearest_below']} / {n['at_cutoff']} / {n['nearest_above']}"
            for n in t["nearest"]
        )
        cross = "; ".join(f"{col}: {sum(m.values())}" for col, m in t["crossings"].items())
        where = f"{t['model']}:{','.join(map(str, t['lines']))}"
        rows.append([t["id"], where, t["clause"], near, cross, t["total_crossings"]])
    return rows


def _decision_groups(exceptions: Exceptions) -> list[list[Any]]:
    """Category-B decisions grouped by reason label: label, reason, cases, decision, date."""
    groups: dict[tuple[str, str, str, str], int] = {}
    for e in exceptions["category_b"]:
        key = (
            e.get("reason_label", ""),
            e.get("reason", ""),
            e.get("decision", ""),
            e.get("decided", ""),
        )
        groups[key] = groups.get(key, 0) + 1
    return [
        [label, reason, n, decision, decided]
        for (label, reason, decision, decided), n in groups.items()
    ]


def _decision_cell(e: dict[str, Any] | None) -> str:
    if not e or not e.get("decision"):
        return "**pending**"
    return f"{e['decision']} (`{e.get('reason_label', '')}`)"


def render(doc: Doc, exceptions: Exceptions) -> str:
    o, loc, e2e, rt = doc["oracle"], doc["local"], doc["e2e"], doc["runtime_s"]
    s, es = loc["summary"], e2e["summary"]
    out = ["# Perturbation oracle report: synthetic_shop", "", INTRO, ""]
    out += [
        f"Oracle v{o['version']}, seed {o['seed']}, dbt-core {o['dbt_core']}, dbt-duckdb "
        f"{o['dbt_duckdb']}, duckdb {o['duckdb']}. Wall time {rt['total']} s (dbt seed + compile "
        f"{rt['dbt_compile']} s, local {rt['local']} s, end-to-end {rt['e2e']} s).",
    ]
    out += ["", "## Summary", ""] + _table(["Check", "Result"], _summary(doc))

    out += ["", "## Local check by edge label", ""]
    out += ["A pair with several labels (JOIN and GROUP_BY, say) counts once per label.", ""]
    by_label = [[k, v["confirmed"], v["not_observed"]] for k, v in loc["by_label"].items()]
    out += _table(["Label", "Confirmed", "Not observed"], by_label)

    out += ["", "## Category A", ""]
    a_modes = {_key(c): ", ".join(c.get("modes", [])) for c in loc["category_a"]}
    out += _table(
        ["From", "To", "Check", "Modes"],
        [[f, t, check, a_modes.get((f, t), "")] for f, t, check in category_a(doc)],
    )

    out += ["", "## Category B: auto-tagged", ""]
    out += _table(["Tag", "Cases"], [[k, v] for k, v in s["category_b_tagged"].items()])
    out += ["", "`row_preserving_join` per child model:", ""]
    per_model = loc["row_preserving_join_by_model"]
    out += _table(["Child model", "Cases"], [[k, v] for k, v in per_model.items()])
    out += ["", "Spot-check sample (10, fixed seed); lines come from a text lookup in the SQL.", ""]
    out += _table(
        ["From (key)", "To", "File", "JOIN line", "Target line"],
        [
            [c["from"], c["to"], c.get("file", ""), _cite(c.get("join_line")),
             _cite(c.get("target_line"))]
            for c in loc["spot_check"]
        ],
    )  # fmt: skip

    out += ["", "## Category B: for the owner", "", OWNER_B, ""]
    decisions = {_key(e): e for e in exceptions["category_b"]}
    out += _table(
        ["From", "To", "Labels", "Note", "Decision"],
        [
            [c["from"], c["to"], ", ".join(c["labels"]), c.get("note", ""),
             _decision_cell(decisions.get(_key(c)))]
            for c in loc["category_b"]
            if not c.get("tag")
        ],
    )  # fmt: skip

    out += ["", "## Indirect edges are real", ""]
    out += [
        f"{s['indirect_only']} local pairs changed although the gold reaches them only through "
        f"indirect pairs. {es['indirect_only']} end-to-end changes lie in the direct+indirect "
        "closure but not in the direct closure. Local pairs by indirect label:",
        "",
    ]
    by = Counter(lb for c in loc["indirect_only"] for lb in c["labels"])
    out += _table(["Label", "Pairs"], [list(kv) for kv in sorted(by.items())])

    out += ["", "## Thresholds", "", THRESHOLDS, ""]
    out += _table(
        [
            "Threshold",
            "Model:lines",
            "Clause",
            "Nearest (below / at / above)",
            "Crossings",
            "Total",
        ],
        _thresholds(doc),
    )

    out += ["", "## Errors", ""]
    out += _table(
        ["Column", "Child", "Mode", "Error"],
        [[x["column"], x["child"], x["mode"], x["error"]] for x in loc["errors"]],
    )

    quiet = loc["no_gold_out_edge"]
    out += ["", "## Columns with nothing to observe", ""]
    out += [
        f"Dead ends (no child model): {len(loc['dead_ends'])}. Columns with children but no gold "
        f"out-edge, and no observed change: {len(quiet)}"
        + (": " + ", ".join(f"`{c}`" for c in quiet) if quiet else "")
        + "."
    ]

    out += ["", "## End to end: unexplained unobserved columns", "", UNEXPLAINED, ""]
    unexplained = []
    for r in e2e["columns"]:
        if not r["unobserved_unexplained"]:
            continue
        groups = {e2e_group(exceptions, r["column"], c) for c in r["unobserved_unexplained"]}
        ref = ", ".join(
            str(g + 1) if g is not None else "**none**" for g in sorted(groups, key=str)
        )
        cols = ", ".join(f"`{c}`" for c in r["unobserved_unexplained"])
        unexplained.append([r["column"], cols, ref])
    out += _table(["Seed column", "Unobserved", "Reason"], unexplained)
    if exceptions["e2e_unexplained"]:
        out += [
            "",
            "Likely reasons (drafted in S05 at the owner's request; in `oracle_exceptions.yml`):",
            "",
        ]
        out += [f"{i}. {g['reason']}" for i, g in enumerate(exceptions["e2e_unexplained"], 1)]

    if exceptions["later_strengthening"]:
        out += ["", "## Possible later strengthening", ""]
        out += [f"- {item}" for item in exceptions["later_strengthening"]]

    out += ["", "## Owner decisions", ""]
    out += ["Rendered from `corpora/synthetic_shop/oracle_exceptions.yml`.", ""]
    if not exceptions["category_a"] and not exceptions["category_b"]:
        out.append("No decisions recorded yet.")
    out += ["Category A:", ""]
    out += _table(
        ["From", "To", "Check", "Reason", "Decision", "Decided"],
        [[e["from"], e["to"], e.get("check", "local"), e.get("reason", ""), e.get("decision", ""),
          e.get("decided", "")] for e in exceptions["category_a"]],
    )  # fmt: skip
    out += ["", "Category B, by reason (each case is listed above, under *for the owner*):", ""]
    out += _table(["Label", "Reason", "Cases", "Decision", "Decided"], _decision_groups(exceptions))
    notes = [e for e in exceptions["category_b"] if e.get("note")]
    if notes:
        out += ["", "Notes:", ""]
        out += [f"- `{e['from']}` -> `{e['to']}`: {e['note']}" for e in notes]
    pending = undecided(doc, exceptions)
    out += [
        "",
        f"Undecided: {len(pending['category_a'])} category A, "
        f"{len(pending['category_b'])} category B.",
        "",
    ]
    return "\n".join(out)
